# Reference values from OrdinaryDiffEqExtrapolation 2.6.4, generated by
# tools/extrapolation-probe.jl: saved points, nf, njacs, nw, nsolve,
# naccept, nreject, the final state and the dense output at two times, then
# the adjusted constructor orders and the error messages.

# long reference comparisons: run on CI (NOT_CRAN = true), not on CRAN
skip_on_cran()

xtp_lv <- function(u, p, t) c(1.5 * u[1] - u[1] * u[2], -3 * u[2] + u[1] * u[2])
xtp_vdp <- function(u, p, t) c(u[2], p[1] * ((1 - u[1] * u[1]) * u[2] - u[1]))
xtp_vdpj <- function(u, p, t) matrix(c(0, p[1] * (-2 * u[1] * u[2] - 1), 1, p[1] * (1 - u[1] * u[1])), 2, 2)
xtp_rob <- function(u, p, t) {
  c(-0.04 * u[1] + 1e4 * u[2] * u[3], 0.04 * u[1] - 1e4 * u[2] * u[3] - 3e7 * u[2] * u[2], 3e7 * u[2] * u[2])
}
xtp_robj <- function(u, p, t) {
  matrix(c(-0.04, 0.04, 0, 1e4 * u[3], -1e4 * u[3] - 6e7 * u[2], 6e7 * u[2], 1e4 * u[2], -1e4 * u[2], 0), 3, 3)
}
xtp_tri <- function(u, p, t) c(-u[1] + u[2] * u[2], -2 * u[2])
xtp_trij <- function(u, p, t) matrix(c(-1, 0, 2 * u[2], -2), 2, 2)
xtp_fd <- function(u, p, t) c(if (u[2] < 0.5) u[1] else -u[1] * u[1], 1)
xtp_probs <- list(
  lv = ODEProblem(xtp_lv, c(1, 1), c(0, 2)),
  lvb = ODEProblem(xtp_lv, c(1, 1), c(2, 0)),
  lvbs = ODEProblem(xtp_lv, c(1, 1), c(2, 1.9)),
  vdp = ODEProblem(ODEFunction(xtp_vdp, jac_fn = xtp_vdpj), c(2, 0), c(0, 1), 10),
  vdps = ODEProblem(ODEFunction(xtp_vdp, jac_fn = xtp_vdpj), c(2, 0), c(0, 0.5), 1000),
  rob = ODEProblem(ODEFunction(xtp_rob, jac_fn = xtp_robj), c(1, 0, 0), c(0, 1)),
  tri = ODEProblem(ODEFunction(xtp_tri, jac_fn = xtp_trij), c(1, 0.5), c(0, 1)),
  fd = ODEProblem(xtp_fd, c(1, 0), c(0, 1))
)
xtp_orders <- function(nm) {
  if (nm == "AitkenNeville") return(list(max_order = 6, init_order = 3))
  if (nm %in% c("ImplicitEulerExtrapolation", "ImplicitEulerBarycentricExtrapolation"))
    return(list(min_order = 3, init_order = 4, max_order = 7))
  list(min_order = 2, init_order = 3, max_order = 6)
}
# case => problem, algorithm arguments, solve arguments (as in the probe)
xtp_case <- function(nm, case) {
  tight <- list(abstol = 1e-8, reltol = 1e-8)
  mid <- list(abstol = 1e-6, reltol = 1e-6)
  explicit <- nm %in% c("AitkenNeville", "ExtrapolationMidpointDeuflhard", "ExtrapolationMidpointHairerWanner")
  base <- if (explicit) "lv" else "vdp"
  dflt <- if (explicit) tight else mid
  cb <- DiscreteCallback(function(u, t, integ) t == 0.5, function(integ) integ$u <- integ$u * 0.9)
  cbd <- ContinuousCallback(function(u, t, integ) u[2] - 0.5, function(integ) NULL)
  s <- switch(case,
    default = list(base, list(), dflt),
    loose = list(base, list(), if (explicit) list(abstol = 1e-6, reltol = 1e-4) else list(abstol = 1e-6, reltol = 1e-3)),
    orders = list(base, xtp_orders(nm), dflt),
    fixed = list(base, list(), list(dt = if (explicit) 0.25 else 0.1, adaptive = FALSE)),
    tstop = list(base, list(), c(dflt, list(tstops = 0.5, callback = cb))),
    back = if (nm == "AitkenNeville") list("lvbs", list(), list(abstol = 1e-6, reltol = 1e-4)) else list("lvb", list(), tight),
    threaded = list(base, list(threading = TRUE), dflt),
    romberg = list(base, list(sequence = "romberg"), dflt),
    bulirsch = list(base, list(sequence = "bulirsch"), dflt),
    sf4 = list(base, list(sequence_factor = 4), dflt),
    sf4serial = list(base, list(sequence_factor = 4, threading = FALSE), dflt),
    serial = list(base, list(threading = FALSE), list(abstol = 1e-6, reltol = 1e-4)),
    rombergthreaded = list(base, list(threading = TRUE, sequence = "romberg"), list(abstol = 1e-6, reltol = 1e-3)),
    stiff = list("vdps", list(), list(abstol = 1e-6, reltol = 1e-4)),
    rob = list("rob", list(), list(abstol = 1e-8, reltol = 1e-6)),
    tri = list("tri", list(), tight),
    disco = list("fd", list(), list(callback = cbd, discontinuity_detection = TRUE, reltol = 1e-6, abstol = 1e-8)),
    nodisco = list("fd", list(), list(callback = cbd, reltol = 1e-6, abstol = 1e-8)))
  ts <- switch(s[[1]], lvb = c(1.63, 0.37), lvbs = c(1.97, 1.93), vdps = c(0.11, 0.37), c(0.37, 0.81))
  list(prob = xtp_probs[[s[[1]]]], alg = do.call(get(nm), s[[2]]), opts = s[[3]], ts = ts)
}
xtp_check <- function(r) {
  cs <- xtp_case(r$alg, r$case)
  sol <- do.call(solve, c(list(cs$prob, cs$alg), cs$opts))
  lab <- paste(r$alg, r$case)
  st <- sol$stats
  expect_identical(as.character(sol$retcode), r$retcode, label = lab)
  expect_identical(length(sol$t), r$n, label = lab)
  got <- c(nf = st$nf, njacs = st$njacs, nw = st$nw, nsolve = st$nsolve, naccept = st$naccept, nreject = st$nreject)
  want <- c(nf = r$nf, njacs = r$njacs, nw = r$nw, nsolve = r$nsolve, naccept = r$naccept, nreject = r$nreject)
  expect_equal(got, want, label = lab)
  expect_equal(sol$u[[length(sol$u)]], r$u, tolerance = 1e-12, label = lab)
  expect_equal(c(sol(cs$ts[1]), sol(cs$ts[2])), r$dense, tolerance = 1e-12, label = lab)
}

