for (xtp_nm in unique(vapply(xtp_ref, function(r) r$alg, ""))) {
  test_that(paste(xtp_nm, "matches OrdinaryDiffEqExtrapolation"), {
    for (r in Filter(function(r) r$alg == xtp_nm, xtp_ref)) xtp_check(r)
  })
}

test_that("the constructors adjust the orders, the sequence and the sequence factor as in Julia", {
  ord <- function(a) c(a$min_order, a$init_order, a$max_order)
  expect_equal(ord(ExtrapolationMidpointDeuflhard(min_order = 0, init_order = -1, max_order = -2)), c(1, 1, 1))
  expect_equal(ord(ExtrapolationMidpointHairerWanner(min_order = 4, init_order = 2, max_order = 3)), c(4, 5, 6))
  expect_equal(ord(ImplicitEulerExtrapolation(min_order = 1, init_order = 1, max_order = 1)), c(3, 4, 5))
  expect_warning(a <- ImplicitEulerBarycentricExtrapolation(min_order = 6, init_order = 2, max_order = 2, sequence = "foo"),
                 "changed from :foo to :harmonic")
  expect_equal(ord(a), c(6, 7, 8))
  expect_identical(a$sequence, "harmonic")
  expect_warning(a <- ExtrapolationMidpointHairerWanner(sequence_factor = 3), "changed from 3 to 2")
  expect_identical(a$sequence_factor, 2L)
  expect_identical(ExtrapolationMidpointDeuflhard(sequence = quote(romberg))$sequence, "romberg")
  expect_identical(AitkenNeville(threading = TRUE)$threading, TRUE)
})

test_that("max_order above 15 and mass matrices are errors as in Julia", {
  msg <- "max_order > 15 not allowed for Float32 or Float64 with this algorithm. That's a bad idea."
  expect_error(solve(xtp_probs$lv, ExtrapolationMidpointDeuflhard(max_order = 16)), msg, fixed = TRUE)
  expect_error(solve(xtp_probs$vdp, ImplicitEulerBarycentricExtrapolation(max_order = 16)), msg, fixed = TRUE)
  # ImplicitEulerExtrapolation builds its sequence without a table
  sol <- solve(xtp_probs$vdp, ImplicitEulerExtrapolation(max_order = 16), abstol = 1e-6, reltol = 1e-6)
  expect_identical(as.character(sol$retcode), "Success")
  mp <- ODEProblem(ODEFunction(xtp_vdp, jac_fn = xtp_vdpj, mass_matrix = diag(c(1, 0))), c(2, 0), c(0, 1), 10)
  expect_error(solve(mp, ImplicitEulerExtrapolation()), "does not support mass matrices")
})
